<div class="head"><div><h1><?= icon('card') ?> My Payments</h1><p class="muted">Pending payments are waiting for staff confirmation.</p></div><a class="btn sm" href="<?= url('bills') ?>">Pay a bill</a></div>
<div class="panel"><div class="tw"><table><tr><th>Date</th><th>Bill</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th></tr><?php foreach ($rows as $p): ?><tr><td><?= e($p['payment_date']) ?></td><td><a href="<?= url('bills/show', ['id' => $p['bill_id']]) ?>"><?= e($p['billing_month']) ?></a></td><td><?= e(money($p['amount_paid'])) ?></td><td><?= e($p['payment_method']) ?></td><td><?= e($p['transaction_reference']) ?></td><td><?= badge($p['status']) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="6" class="muted">No payments yet.</td></tr><?php endif; ?></table></div></div>
